-- Marks that the China Section 301 line data (migrations 0080 to 0084) is loaded, so the duty stack can say a line is "not covered" instead of "not evaluated".
-- Applied last on purpose: if an earlier file fails, this one is not applied and the duty stack keeps saying "not evaluated".
INSERT INTO tariff_overlays (program, hts_pattern, country_scope, rate_pct, rate_type, legal_basis, effective_date, expiration_date, exclusions, stacking_rule, source_url, source_tier, last_updated, data_as_of) VALUES ('sec301_china_coverage', '%', 'CN', NULL, 'ad_valorem', 'Coverage record, not a duty: the China Section 301 product lists in this app are Lists 1, 2, 3 and 4A (HTSUS 9903.88.01, .02, .03, .15) and the four-year review increases of U.S. note 31 (9903.91.01 to 9903.91.11, 9903.92.10), read from HTS 2026 Revision 23. Exclusions in U.S. notes 20(vvv) and 20(www) are handled by forcing review. Not modelled: exclusions after Revision 23, Section 301 shipbuilding fees, and notes not yet in the HTS.', '2018-07-06', NULL, NULL, 'Lines are in program sec301_china; a China-origin line with no row there is not covered by these actions in this revision of the HTS.', 'https://hts.usitc.gov/reststop/file?release=2026HTSRev23&filename=Chapter%2099', 1, '2026-11-22', '2026-11-22');
